<?php if(is_manager()): $metricStmt=$pdo->prepare('SELECT u.full_name,u.user_code,COUNT(DISTINCT CASE WHEN t.status<>"Closed" THEN t.id END) current_tickets,COUNT(DISTINCT CASE WHEN t.status="Closed" THEN t.id END) closed_tickets FROM users u LEFT JOIN tickets t ON t.assigned_to=u.id WHERE u.company_id=? AND u.role<>"manager" GROUP BY u.id ORDER BY u.full_name');$metricStmt->execute([current_user()['company_id']]);$metricEmployees=$metricStmt->fetchAll(); ?><section class="card pilot-metrics"><div class="section-head" style="margin-top:0"><div><h2>Employee ticket metrics</h2><p class="muted">Current ownership and completed delivery by employee.</p></div><span class="metric-total"><?=count($metricEmployees)?> employees</span></div><div class="metric-grid"><div class="metric-heading">Employee</div><div class="metric-heading">Current tickets</div><div class="metric-heading">Tickets closed</div><?php foreach($metricEmployees as $metric): ?><div class="metric-name"><strong><?=e($metric['full_name'])?></strong><span class="muted">@<?=e($metric['user_code'])?></span></div><div class="metric-number current"><?=e((string)$metric['current_tickets'])?></div><div class="metric-number closed"><?=e((string)$metric['closed_tickets'])?></div><?php endforeach; ?></div><?php if(!$metricEmployees): ?><div class="empty">No employees have been added yet.</div><?php endif; ?></section><?php endif; ?>
